export function cardCopy(card) {
  const entry = CARD_COPY[card.number];
  return entry?.[0] === card.name ? { title: `${entry[0]}: ${entry[1]}`, body: entry[2] }
    : { title: `${card.name}: тема дня`, body: `${card.focus.charAt(0).toUpperCase()}${card.focus.slice(1)}.` };
}
